import{_ as i,o as a,c as s,ak as t}from"./chunks/framework.Dpc0wyhY.js";const k=JSON.parse('{"title":"Data Modeling Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"guides/data-modeling.md","filePath":"guides/data-modeling.md"}'),o={name:"guides/data-modeling.md"};function n(l,e,d,r,h,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="data-modeling-recipes" tabindex="-1">Data Modeling Recipes <a class="header-anchor" href="#data-modeling-recipes" aria-label="Permalink to “Data Modeling Recipes”">​</a></h1><p>Patterns for structuring collections, relationships, and layouts that are known to work cleanly over the API.</p><h2 id="collection-folders" tabindex="-1">Collection Folders <a class="header-anchor" href="#collection-folders" aria-label="Permalink to “Collection Folders”">​</a></h2><p>A folder is a collection with <code>schema: null</code>. Create it once, then file collections into it by setting <code>meta.group</code> on each:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PATCH /collections/{name}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;meta&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;group&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyApp&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> }</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> }</span></span></code></pre></div><p>Folders keep the navigation sidebar manageable on instances with many collections.</p><h2 id="audit-fields-are-not-automatic" tabindex="-1">Audit Fields Are Not Automatic <a class="header-anchor" href="#audit-fields-are-not-automatic" aria-label="Permalink to “Audit Fields Are Not Automatic”">​</a></h2><p>Setting <code>meta.accountability: &quot;all&quot;</code> on a collection does <strong>not</strong> create <code>user_created</code>, <code>date_created</code>, <code>user_updated</code>, or <code>date_updated</code> — the meta flag says <code>all</code> while zero fields exist. Create them explicitly:</p><ol><li>Four fields: <code>user_created</code> (uuid, special <code>user-created</code>), <code>date_created</code> (timestamp, special <code>date-created</code>), <code>user_updated</code> (uuid, special <code>user-updated</code>), <code>date_updated</code> (timestamp, special <code>date-updated</code>). Mark each <code>readonly</code> + <code>hidden</code>.</li><li>Then POST the two M2O relations — <code>user_created</code> and <code>user_updated</code> — to the <code>system_users</code> collection.</li></ol><p>Skip step 2 and the fields store a UUID they cannot resolve, surfacing as a &quot;relationship not configured&quot; error in the app.</p><h2 id="reverse-o2m-aliases" tabindex="-1">Reverse O2M Aliases <a class="header-anchor" href="#reverse-o2m-aliases" aria-label="Permalink to “Reverse O2M Aliases”">​</a></h2><p>A reverse one-to-many alias field is created automatically by setting <code>meta.one_field</code> on the relation POST. Then PATCH <code>/fields/{collection}/{alias}</code> to set:</p><ul><li><code>interface: list-o2m</code></li><li><code>options.template</code> — the display template for each row</li><li><code>meta.group</code> — which tab group the field lands in</li></ul><h2 id="many-to-many-junctions" tabindex="-1">Many-to-Many Junctions <a class="header-anchor" href="#many-to-many-junctions" aria-label="Permalink to “Many-to-Many Junctions”">​</a></h2><p>M2M needs <code>junction_field</code> set on the junction→parent relation <strong>on both sides</strong>, plus patching the alias field to <code>interface: list-m2m</code> (or <code>files</code> for file galleries). A missing second side produces &quot;relationship not configured&quot; in the app.</p><p>If the relation was created without <code>junction_field</code> on both sides, fix it with the <a href="/guides/automation-recipes.html#the-sql-query-operation">SQL Query operation</a> rather than trying to PATCH the relation — then <a href="/guides/api-notes.html#prefer-recreating-relations-over-updating-them">clear the schema cache</a>.</p><h3 id="prefer-o2m-junctions-when-you-need-per-link-data" tabindex="-1">Prefer O2M Junctions When You Need Per-Link Data <a class="header-anchor" href="#prefer-o2m-junctions-when-you-need-per-link-data" aria-label="Permalink to “Prefer O2M Junctions When You Need Per-Link Data”">​</a></h3><p>When each link needs its own fields (a role, a statement, a charged price), model the &quot;junction&quot; as a regular collection with two M2O relations and edit it through the parent&#39;s <code>list-o2m</code> alias. You get inline editing, and the <code>junction_field</code> problem disappears entirely.</p><h3 id="junction-keys-must-stay-visible" tabindex="-1">Junction Keys Must Stay Visible <a class="header-anchor" href="#junction-keys-must-stay-visible" aria-label="Permalink to “Junction Keys Must Stay Visible”">​</a></h3><p>Do not set <code>hidden: true</code> on the FK fields of a junction (the parent key, the related key, or the <code>system_files</code> key). Hiding them breaks <code>list-m2m</code> and <code>files</code> interfaces with &quot;relationship not configured&quot;.</p><h3 id="cascading-deletes" tabindex="-1">Cascading Deletes <a class="header-anchor" href="#cascading-deletes" aria-label="Permalink to “Cascading Deletes”">​</a></h3><p><code>one_deselect_action</code> can&#39;t be changed reliably after creation. Either delete junction rows before deleting the parent, or enforce it at the database level:</p><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app_work_orders_files</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  DROP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> CONSTRAINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app_work_orders_files_work_order_foreign,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ADD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> CONSTRAINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app_work_orders_files_work_order_foreign</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  FOREIGN KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (work_order) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REFERENCES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app_work_orders(id) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON DELETE CASCADE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Then update the relations registry so the app knows the link deletes children (<code>one_deselect_action = &#39;delete&#39;</code> on the junction&#39;s parent field), and clear the schema cache.</p><h2 id="tab-layouts-group-fields" tabindex="-1">Tab Layouts (Group Fields) <a class="header-anchor" href="#tab-layouts-group-fields" aria-label="Permalink to “Tab Layouts (Group Fields)”">​</a></h2><p>Tabbed item pages are built from group fields, no extensions required:</p><ul><li>Each tab is a field of <code>type: alias</code> with <code>special: [&quot;alias&quot;, &quot;group&quot;, &quot;no-data&quot;]</code> — for example <code>grp_tabs</code>.</li><li>Child fields point at their tab via <code>meta.group</code>.</li><li>Set <code>meta.translations</code> on the group field for tab labels.</li></ul><p>This scales to deep layouts — five- and seven-tab detail pages are routine.</p><h2 id="singletons" tabindex="-1">Singletons <a class="header-anchor" href="#singletons" aria-label="Permalink to “Singletons”">​</a></h2><p>A singleton collection rejects <code>POST /items/{collection}</code> with <code>ROUTE_NOT_FOUND</code> — the row already exists. Use PATCH instead.</p><h2 id="list-o2m-display-options" tabindex="-1">list-o2m Display Options <a class="header-anchor" href="#list-o2m-display-options" aria-label="Permalink to “list-o2m Display Options”">​</a></h2><p><code>options.fields: [&quot;a&quot;, &quot;b&quot;]</code> renders junction rows as real table columns, not just a template string. Useful companions: <code>options.sortField</code>, <code>enableLink</code>, <code>enableCreate</code>, <code>enableSelect</code>, <code>enableSearchFilter</code>.</p><p>To hide a pure junction collection from the navigation while keeping it editable through its parent, set <code>meta.hidden: true</code> on the collection.</p><h2 id="m2o-pickers-need-a-template" tabindex="-1">M2O Pickers Need a Template <a class="header-anchor" href="#m2o-pickers-need-a-template" aria-label="Permalink to “M2O Pickers Need a Template”">​</a></h2><p>Without <code>options.template</code>, a many-to-one dropdown renders raw UUIDs. Always set a display template.</p><h2 id="geometry-fields" tabindex="-1">Geometry Fields <a class="header-anchor" href="#geometry-fields" aria-label="Permalink to “Geometry Fields”">​</a></h2><p>Field types are namespace-prefixed: <code>type: &quot;point&quot;</code> is rejected — use <code>geometry.Point</code>, <code>geometry.MultiPolygon</code>, or plain <code>geometry</code>. Payloads accept and return GeoJSON objects:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Point&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;coordinates&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120.9842</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14.5995</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>Remember: <strong>longitude first</strong>, then latitude.</p><p>Map interface options:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;basemap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OpenStreetMap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultView&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;center&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;lat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14.5995</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;lng&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120.9842</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zoom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">13</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>OpenStreetMap needs no API token.</p>`,42)])])}const u=i(o,[["render",n]]);export{k as __pageData,u as default};
